import { index, integer, real, sqliteTable, text } from 'drizzle-orm/sqlite-core';

/**
 * Local (offline) database. Mirrors the seller's working set downloaded by
 * `GET /sync/pull` plus what the seller creates offline (queued in `outbox`).
 *
 * Conventions:
 * - Ids are the server ids (UUIDs, generated by the app for what it creates).
 * - Instants are ISO 8601 UTC strings (`toISOString()`), so text order = time order.
 * - `sync_status`: SYNCED (matches the server), PENDING (local changes queued) or
 *   REJECTED (the server refused a queued change; see the outbox for the reason).
 */

const syncStatus = () => text('sync_status').notNull().default('SYNCED');

export const customers = sqliteTable(
  'customers',
  {
    id: text('id').primaryKey(),
    status: text('status').notNull(),
    tradeName: text('trade_name').notNull(),
    businessName: text('business_name'),
    identificationType: text('identification_type'),
    identification: text('identification'),
    contactName: text('contact_name'),
    phone: text('phone'),
    email: text('email'),
    address: text('address'),
    addressReference: text('address_reference'),
    latitude: real('latitude'),
    longitude: real('longitude'),
    storePhotoUrl: text('store_photo_url'),
    /** Photo taken offline, shown until the server URL arrives. */
    storePhotoLocalUri: text('store_photo_local_uri'),
    assignedSellerId: text('assigned_seller_id'),
    createdById: text('created_by_id'),
    externalId: text('external_id'),
    billingSyncStatus: text('billing_sync_status').notNull().default('NOT_REQUIRED'),
    isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
    syncStatus: syncStatus(),
    createdAt: text('created_at').notNull(),
    updatedAt: text('updated_at').notNull(),
  },
  (table) => [
    index('customers_trade_name_idx').on(table.tradeName),
    index('customers_identification_idx').on(table.identification),
  ],
);

export const visits = sqliteTable(
  'visits',
  {
    id: text('id').primaryKey(),
    type: text('type').notNull(),
    status: text('status').notNull(),
    outcome: text('outcome'),
    scheduledAt: text('scheduled_at').notNull(),
    notes: text('notes'),
    startedAt: text('started_at'),
    startLatitude: real('start_latitude'),
    startLongitude: real('start_longitude'),
    startAccuracyMeters: real('start_accuracy_meters'),
    endedAt: text('ended_at'),
    endLatitude: real('end_latitude'),
    endLongitude: real('end_longitude'),
    endAccuracyMeters: real('end_accuracy_meters'),
    distanceToCustomerMeters: real('distance_to_customer_meters'),
    durationMinutes: integer('duration_minutes'),
    photoUrl: text('photo_url'),
    photoLocalUri: text('photo_local_uri'),
    cancellationReason: text('cancellation_reason'),
    sellerId: text('seller_id').notNull(),
    sellerName: text('seller_name'),
    createdById: text('created_by_id').notNull(),
    customerId: text('customer_id').notNull(),
    parentVisitId: text('parent_visit_id'),
    syncStatus: syncStatus(),
    createdAt: text('created_at').notNull(),
    updatedAt: text('updated_at').notNull(),
  },
  (table) => [
    index('visits_scheduled_at_idx').on(table.scheduledAt),
    index('visits_customer_id_idx').on(table.customerId),
    index('visits_status_idx').on(table.status),
  ],
);

export const categories = sqliteTable('categories', {
  id: text('id').primaryKey(),
  code: text('code').notNull(),
  name: text('name').notNull(),
  description: text('description'),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
});

export const products = sqliteTable(
  'products',
  {
    id: text('id').primaryKey(),
    code: text('code').notNull(),
    name: text('name').notNull(),
    brand: text('brand'),
    description: text('description'),
    categoryId: text('category_id').notNull(),
    categoryName: text('category_name').notNull(),
    /** Unit price without VAT (USD). */
    basePrice: real('base_price').notNull(),
    taxRate: real('tax_rate').notNull(),
    priceWithTax: real('price_with_tax').notNull(),
    unitOfMeasure: text('unit_of_measure').notNull(),
    stockQuantity: integer('stock_quantity').notNull(),
    imageUrl: text('image_url'),
    isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  },
  (table) => [
    index('products_name_idx').on(table.name),
    index('products_category_id_idx').on(table.categoryId),
  ],
);

export const promotions = sqliteTable('promotions', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  description: text('description'),
  discountType: text('discount_type').notNull(),
  discountValue: real('discount_value').notNull(),
  targetType: text('target_type').notNull(),
  targetCategoryId: text('target_category_id'),
  targetProductIds: text('target_product_ids', { mode: 'json' }).$type<string[]>().notNull(),
  minQuantity: integer('min_quantity').notNull(),
  startsAt: text('starts_at').notNull(),
  endsAt: text('ends_at').notNull(),
});

export const orders = sqliteTable(
  'orders',
  {
    id: text('id').primaryKey(),
    /** Official number (ORD-000123); null until the server accepts the order. */
    orderNumber: text('order_number'),
    customerId: text('customer_id').notNull(),
    customerName: text('customer_name'),
    visitId: text('visit_id'),
    sellerId: text('seller_id').notNull(),
    status: text('status').notNull(),
    subtotal: real('subtotal').notNull(),
    discountTotal: real('discount_total').notNull(),
    taxTotal: real('tax_total').notNull(),
    total: real('total').notNull(),
    estimatedDeliveryDate: text('estimated_delivery_date'),
    notes: text('notes'),
    billingSyncStatus: text('billing_sync_status').notNull().default('NOT_REQUIRED'),
    invoiceNumber: text('invoice_number'),
    /** Lines whose price the server changed (from the push result). */
    priceAdjustments: text('price_adjustments', { mode: 'json' }).$type<
      { productId: string; expectedUnitPrice: number; unitPrice: number }[]
    >(),
    syncStatus: syncStatus(),
    createdAt: text('created_at').notNull(),
    updatedAt: text('updated_at').notNull(),
  },
  (table) => [
    index('orders_created_at_idx').on(table.createdAt),
    index('orders_customer_id_idx').on(table.customerId),
    index('orders_visit_id_idx').on(table.visitId),
  ],
);

export const orderItems = sqliteTable(
  'order_items',
  {
    id: text('id').primaryKey(),
    orderId: text('order_id')
      .notNull()
      .references(() => orders.id, { onDelete: 'cascade' }),
    productId: text('product_id').notNull(),
    productCode: text('product_code').notNull(),
    productName: text('product_name').notNull(),
    quantity: integer('quantity').notNull(),
    unitPrice: real('unit_price').notNull(),
    discount: real('discount').notNull(),
    totalPrice: real('total_price').notNull(),
    taxRate: real('tax_rate').notNull(),
    taxAmount: real('tax_amount').notNull(),
    promotionName: text('promotion_name'),
  },
  (table) => [index('order_items_order_id_idx').on(table.orderId)],
);

/** Queue of mutations waiting for `POST /sync/push`, in the order they happened. */
export const outbox = sqliteTable(
  'outbox',
  {
    seq: integer('seq').primaryKey({ autoIncrement: true }),
    idempotencyKey: text('idempotency_key').notNull().unique(),
    entityType: text('entity_type').notNull(),
    entityId: text('entity_id').notNull(),
    action: text('action').notNull(),
    payload: text('payload', { mode: 'json' }).$type<Record<string, unknown>>().notNull(),
    clientTimestamp: text('client_timestamp').notNull(),
    /** Photo the payload needs: its server URL is injected into `photoField` at push time. */
    photoId: text('photo_id'),
    photoField: text('photo_field'),
    /** PENDING (to send) or REJECTED (kept to show the error to the seller). */
    status: text('status').notNull().default('PENDING'),
    attempts: integer('attempts').notNull().default(0),
    lastErrorCode: text('last_error_code'),
    lastErrorMessage: text('last_error_message'),
    createdAt: text('created_at').notNull(),
  },
  (table) => [
    index('outbox_status_idx').on(table.status),
    index('outbox_entity_id_idx').on(table.entityId),
  ],
);

/** Photos taken offline, uploaded with `POST /files/photos` before the push. */
export const pendingPhotos = sqliteTable('pending_photos', {
  id: text('id').primaryKey(),
  localUri: text('local_uri').notNull(),
  remoteUrl: text('remote_url'),
  attempts: integer('attempts').notNull().default(0),
  lastError: text('last_error'),
  createdAt: text('created_at').notNull(),
});

/** Key/value sync bookkeeping: pull cursor, last sync time, owner user id. */
export const syncMeta = sqliteTable('sync_meta', {
  key: text('key').primaryKey(),
  value: text('value').notNull(),
});
